#!/usr/bin/env node
/**
 * Builds the committed public boundary benchmark fixture set from OpenStreetMap.
 *
 * Reference polygons are real, publicly mapped car-dealership *areas* — sites
 * where the operational lot itself is drawn in OSM, not just a point or the
 * showroom building. That is the closest thing to ground truth that can be
 * redistributed: it is ODbL-licensed open data, contains no customer
 * information, and can be regenerated by anyone.
 *
 * Run manually and commit the output. This is not part of the test run; the
 * benchmark reads the committed file so CI never depends on Overpass.
 *
 *   node scripts/build-public-boundary-fixtures.mjs
 *   node scripts/build-public-boundary-fixtures.mjs --out resources/benchmarks/boundary-public-fixtures.json
 */

import { writeFileSync } from "node:fs";
import { resolve } from "node:path";

const OVERPASS_MIRRORS = [
  "https://overpass-api.de/api/interpreter",
  "https://lz4.overpass-api.de/api/interpreter",
  "https://overpass.kumi.systems/api/interpreter",
];
const USER_AGENT = "DealershipRiskMapping-Desktop/0.1 (benchmark fixture builder)";

/**
 * Regions to sample. The seven ALKIS states come first because the cadastre
 * path only exists there; the remaining entries exercise the OSM/imagery
 * fallback that everywhere else depends on.
 */
/**
 * Regions to sample, each as a city-sized bbox [south, west, north, east].
 *
 * Whole-state `area[...]` queries time out on the public Overpass instance
 * often enough to make the build unreproducible, which defeats the point of a
 * committed fixture set. A bounded bbox is cheap, polite, and deterministic.
 *
 * The seven ALKIS states come first because the cadastre path only exists
 * there; the rest exercise the OSM/imagery fallback everywhere else depends on.
 */
const REGIONS = [
  { key: "de-nw", state: "NRW", country: "DE", cadastre: true, areas: [
    { city: "Koeln", bbox: [50.86, 6.80, 51.02, 7.08] },
    { city: "Dortmund", bbox: [51.46, 7.36, 51.56, 7.58] } ] },
  { key: "de-be", state: "Berlin", country: "DE", cadastre: true, areas: [
    { city: "Berlin-West", bbox: [52.43, 13.20, 52.58, 13.40] },
    { city: "Berlin-Ost", bbox: [52.43, 13.40, 52.60, 13.62] } ] },
  { key: "de-sn", state: "Sachsen", country: "DE", cadastre: true, areas: [
    { city: "Leipzig", bbox: [51.26, 12.26, 51.41, 12.50] },
    { city: "Dresden", bbox: [51.00, 13.66, 51.12, 13.86] } ] },
  { key: "de-ni", state: "Niedersachsen", country: "DE", cadastre: true, areas: [
    { city: "Hannover", bbox: [52.31, 9.62, 52.44, 9.86] },
    { city: "Braunschweig", bbox: [52.22, 10.44, 52.32, 10.62] } ] },
  { key: "de-sh", state: "Schleswig-Holstein", country: "DE", cadastre: true, areas: [
    { city: "Kiel", bbox: [54.25, 10.02, 54.40, 10.26] },
    { city: "Luebeck", bbox: [53.82, 10.60, 53.92, 10.80] } ] },
  { key: "de-st", state: "Sachsen-Anhalt", country: "DE", cadastre: true, areas: [
    { city: "Magdeburg", bbox: [52.06, 11.54, 52.20, 11.74] },
    { city: "Halle", bbox: [51.44, 11.90, 51.55, 12.06] } ] },
  { key: "de-bb", state: "Brandenburg", country: "DE", cadastre: true, areas: [
    { city: "Potsdam", bbox: [52.33, 12.92, 52.46, 13.18] },
    { city: "Cottbus", bbox: [51.70, 14.26, 51.80, 14.42] } ] },
  { key: "de-by", state: "Bayern", country: "DE", cadastre: false, areas: [
    { city: "Muenchen", bbox: [48.08, 11.45, 48.22, 11.70] },
    { city: "Nuernberg", bbox: [49.40, 10.99, 49.51, 11.18] } ] },
  { key: "de-he", state: "Hessen", country: "DE", cadastre: false, areas: [
    { city: "Frankfurt", bbox: [50.05, 8.53, 50.20, 8.78] },
    { city: "Kassel", bbox: [51.26, 9.40, 51.36, 9.56] } ] },
  { key: "at-9", state: "Wien", country: "AT", cadastre: false, areas: [
    { city: "Wien", bbox: [48.15, 16.30, 48.28, 16.50] },
    { city: "Linz", bbox: [48.24, 14.22, 48.34, 14.38] } ] },
  { key: "nl-zh", state: "Zuid-Holland", country: "NL", cadastre: false, areas: [
    { city: "Rotterdam", bbox: [51.86, 4.36, 51.99, 4.58] },
    { city: "DenHaag", bbox: [52.03, 4.23, 52.12, 4.40] } ] },
];

/** Plausible operational-lot area. Below is a showroom; above is a business park. */
const MIN_AREA_SQM = 3_000;
const MAX_AREA_SQM = 60_000;
/** Keep the set small and reviewable. */
const PER_REGION = 2;
/**
 * A 4-corner box is a mapper's placeholder, not a digitised outline. Using one
 * as a reference would mostly measure how well the engine reproduces someone
 * else's rectangle.
 */
const MIN_VERTICES = 8;

const METERS_PER_DEGREE = 111_320;

function ringAreaSqm(ring) {
  if (ring.length < 4) return 0;
  const cosLat = Math.cos((ring[0][1] * Math.PI) / 180);
  let area = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    const x1 = (ring[i][0] - ring[0][0]) * METERS_PER_DEGREE * cosLat;
    const y1 = (ring[i][1] - ring[0][1]) * METERS_PER_DEGREE;
    const x2 = (ring[i + 1][0] - ring[0][0]) * METERS_PER_DEGREE * cosLat;
    const y2 = (ring[i + 1][1] - ring[0][1]) * METERS_PER_DEGREE;
    area += x1 * y2 - x2 * y1;
  }
  return Math.abs(area / 2);
}

function centroidOf(ring) {
  let lon = 0;
  let lat = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    lon += ring[i][0];
    lat += ring[i][1];
  }
  const n = ring.length - 1;
  return [lon / n, lat / n];
}

function closeRing(ring) {
  const first = ring[0];
  const last = ring[ring.length - 1];
  if (first[0] !== last[0] || first[1] !== last[1]) ring.push([...first]);
  return ring;
}

/** Rejects slivers and near-degenerate shapes that make poor references. */
function isPlausibleLot(ring) {
  if (ring.length - 1 < MIN_VERTICES) return false;
  const area = ringAreaSqm(ring);
  if (area < MIN_AREA_SQM || area > MAX_AREA_SQM) return false;
  let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
  for (const [lon, lat] of ring) {
    minLon = Math.min(minLon, lon); maxLon = Math.max(maxLon, lon);
    minLat = Math.min(minLat, lat); maxLat = Math.max(maxLat, lat);
  }
  const cosLat = Math.cos((minLat * Math.PI) / 180);
  const width = (maxLon - minLon) * METERS_PER_DEGREE * cosLat;
  const height = (maxLat - minLat) * METERS_PER_DEGREE;
  if (width < 20 || height < 20) return false;
  const aspect = Math.max(width, height) / Math.min(width, height);
  if (aspect > 6) return false;
  // A lot should fill a decent share of its bounding box.
  return area / (width * height) > 0.45;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Tries each mirror, then backs off and retries. 504/429 are routine here. */
async function overpass(query, attempts = 3) {
  let lastError = new Error("no attempt made");
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    for (const url of OVERPASS_MIRRORS) {
      try {
        const res = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "text/plain", "User-Agent": USER_AGENT },
          body: query,
        });
        if (res.ok) return res.json();
        lastError = new Error(`${res.status} ${res.statusText}`);
      } catch (error) {
        lastError = error;
      }
      await sleep(1_000);
    }
    await sleep(3_000 * 2 ** attempt);
  }
  throw lastError;
}

async function fetchRegion(region) {
  const candidates = [];
  for (const area of region.areas) {
    const [south, west, north, east] = area.bbox;
    const query = `
[out:json][timeout:90][bbox:${south},${west},${north},${east}];
way["shop"="car"]["name"];
out geom 400;`;
    const data = await overpass(query);
    for (const element of data.elements ?? []) {
      if (element.type !== "way" || !Array.isArray(element.geometry)) continue;
      if (element.geometry.length < 4) continue;
      const ring = closeRing(element.geometry.map((p) => [p.lon, p.lat]));
      if (!isPlausibleLot(ring)) continue;
      const [lon, lat] = centroidOf(ring);
      candidates.push({
        id: `${region.key}-${element.id}`,
        osmType: "way",
        osmId: element.id,
        lon: Number(lon.toFixed(6)),
        lat: Number(lat.toFixed(6)),
        areaSqm: Math.round(ringAreaSqm(ring)),
        vertices: ring.length - 1,
        country: region.country,
        state: region.state,
        city: area.city,
        cadastreAvailable: region.cadastre,
        reference: {
          type: "Polygon",
          coordinates: [
            ring.map(([x, y]) => [Number(x.toFixed(7)), Number(y.toFixed(7))]),
          ],
        },
      });
    }
    await sleep(1_500);
  }
  // Prefer the richest outlines available in the region.
  candidates.sort((a, b) => b.vertices - a.vertices);
  return candidates.slice(0, PER_REGION);
}

async function main() {
  const outArg = process.argv.indexOf("--out");
  const outPath = resolve(
    outArg === -1
      ? "resources/benchmarks/boundary-public-fixtures.json"
      : process.argv[outArg + 1],
  );

  const samples = [];
  for (const region of REGIONS) {
    process.stdout.write(`${region.key} ... `);
    try {
      const found = await fetchRegion(region);
      samples.push(...found);
      console.log(`${found.length} sample(s)`);
    } catch (error) {
      console.log(`failed (${error.message})`);
    }
    // Be a good citizen on the shared public instance.
    await sleep(2_000);
  }

  // Geographic hold-out, not a random split: whole regions are held out so a
  // site cannot leak into tuning via a neighbour a few hundred metres away.
  const holdoutRegions = new Set(["de-sh", "de-st", "at-9", "nl-zh"]);
  for (const sample of samples) {
    const region = REGIONS.find((r) => r.state === sample.state);
    sample.holdout = holdoutRegions.has(region?.key ?? "");
  }

  const payload = {
    dataset: "boundary-public-v1",
    license: "ODbL-1.0",
    attribution: "© OpenStreetMap contributors",
    generatedAt: new Date().toISOString().slice(0, 10),
    note:
      "Reference polygons are publicly mapped car-dealership areas in OSM. " +
      "They are a proxy for the operational lot, not a survey: OSM mappers " +
      "vary in how much of the forecourt and staff parking they include.",
    holdoutRegions: [...holdoutRegions],
    samples: samples.sort((a, b) => a.id.localeCompare(b.id)),
  };

  writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `\nwrote ${samples.length} samples (${samples.filter((s) => s.holdout).length} held out) to ${outPath}`,
  );
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
